/**
 * Mock secure report shares (Epic 4).
 * Tokens model unique email links generated by ClaudMD when a report is shared.
 * Expiration is evaluated client-side for the demo.
 */

const DAY_MS = 24 * 60 * 60 * 1000;

/** Active demo share — Maria Garcia Annual Physical (Mar 20, 2026). */
export const DEMO_SECURE_SHARE_TOKEN = "shr_mg_phys_20260320";

/** Expired demo share for US-4.1 expiration acceptance. */
export const DEMO_EXPIRED_SHARE_TOKEN = "shr_expired_demo";

export const secureShares = [
  {
    token: DEMO_SECURE_SHARE_TOKEN,
    /** Links to `sharedDocuments` id */
    sharedDocumentId: "sd-012",
    employeeId: "ee-005",
    recipientEmail: "employer@demo.com",
    recipientRole: "employer",
    /** Minimal non-PHI email content (US-4.1) */
    patientName: "Maria Garcia",
    reportType: "Physical Results",
    visitLabel: "Annual Physical",
    visitDate: "Mar 20, 2026",
    /** Far-future so the demo link stays usable */
    expiresAt: "2027-12-31T23:59:59.000Z",
    sharedAt: "2026-03-21T14:30:00.000Z",
  },
  {
    token: DEMO_EXPIRED_SHARE_TOKEN,
    sharedDocumentId: "sd-012",
    employeeId: "ee-005",
    recipientEmail: "employer@demo.com",
    recipientRole: "employer",
    patientName: "Maria Garcia",
    reportType: "Physical Results",
    visitLabel: "Annual Physical",
    visitDate: "Mar 20, 2026",
    expiresAt: "2026-03-28T23:59:59.000Z",
    sharedAt: "2026-03-21T14:30:00.000Z",
  },
];

export function findSecureShare(token) {
  if (!token) return null;
  return secureShares.find((share) => share.token === token) || null;
}

export function isSecureShareExpired(share, now = Date.now()) {
  if (!share?.expiresAt) return true;
  const expires = Date.parse(share.expiresAt);
  if (Number.isNaN(expires)) return true;
  return expires <= now;
}

/** Helper for demo emails — relative expiry label. */
export function getSecureShareExpiryDays(share, now = Date.now()) {
  if (!share?.expiresAt) return 0;
  const expires = Date.parse(share.expiresAt);
  if (Number.isNaN(expires)) return 0;
  return Math.max(0, Math.ceil((expires - now) / DAY_MS));
}
